<?php
require_once __DIR__.'/../bootstrap/app.php';use GymPro\Services\CommissionService;require_role('SUPER_ADMIN');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{CommissionService::payout((int)$_POST['trainer_id'],(int)current_user()['UserID']);set_flash('success','Commission payout recorded.');redirect('admin/payouts.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$trainers=db_all("SELECT t.TrainerID,t.Name,COALESCE(SUM(CASE WHEN ce.Status='EARNED' THEN ce.Amount ELSE 0 END),0) Earned FROM TRAINER t LEFT JOIN COMMISSION_ENTRY ce ON ce.TrainerID=t.TrainerID GROUP BY t.TrainerID,t.Name ORDER BY t.Name");$payouts=db_all('SELECT p.*,t.Name TrainerName,u.Email RecordedBy FROM PAYOUT p JOIN TRAINER t ON t.TrainerID=p.TrainerID JOIN USER_ACCOUNT u ON u.UserID=p.CreatedBy ORDER BY p.PaidAt DESC LIMIT 100');$pageTitle='Commission payouts';$pageSubtitle='Immutable payout allocation to earned entries';include ROOT_PATH.'/includes/header.php';?><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="card-grid compact"><?php foreach($trainers as $t):?><article class="visit-card"><div><strong><?=e($t['Name'])?></strong><small>Earned: Rs.<?=number_format((float)$t['Earned'],2)?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="trainer_id" value="<?=$t['TrainerID']?>"><button class="btn btn-success btn-sm" <?=$t['Earned']<=0?'disabled':''?>>Record payout</button></form></article><?php endforeach;?></div><div class="section-header section-spaced"><h2 class="section-title">Payout history</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Reference</th><th scope="col">Trainer</th><th scope="col">Amount</th><th scope="col">Paid</th><th scope="col">Recorded by</th></tr></thead><tbody><?php foreach($payouts as $p):?><tr><td><?=e($p['Reference'])?></td><td><?=e($p['TrainerName'])?></td><td>Rs.<?=number_format((float)$p['Amount'],2)?></td><td><?=e(date('d M Y H:i',strtotime($p['PaidAt'])))?></td><td><?=e($p['RecordedBy'])?></td></tr><?php endforeach;?></tbody></table></div><?php include ROOT_PATH.'/includes/footer.php';?>
